#!/usr/bin/env python3
"""Persist L13 independent source-first review; leave author objects unchanged."""
import collections,datetime,hashlib,json,sys
from pathlib import Path
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'scripts'))
from validate import CHECK_KEYS,question_hash
load=lambda p:json.loads((R/p).read_text())
blindpath=R/'audits/blind-answers-W03-L13-independent.json';blind=load(blindpath)
assert blind['complete'] and blind['solvedBeforeAnswerSeen'] and not blind['keyedBatchOpened']
packet=load('audits/blind-W03-L13.json');batchpath=R/'data/question-batches/W03-L13.json';batch=load(batchpath)
qs={q['id']:q for q in batch['questions']};answers={a['questionId']:a for a in blind['answers']}
assert len(qs)==len(answers)==len(packet)==46
for p in packet:
 q=qs[p['id']]
 for key in ['stem','version','selectionMode','options','assumptions','difficulty']:assert q[key]==p[key]
 assert question_hash(q)==p['questionSha256']
 assert set(q['correctOptionIds'])==set(answers[q['id']]['independentAnswerOptionIds'])
comp=load('audits/W03-L13-independent-computations.json');assert comp['allPassed'] and comp['caseCount']==2516
flags={}
def flag(i,key,finding):flags.setdefault(f'W03-L13-Q{i:03d}',[]).append({'check':key,'finding':finding})
for i,reason in {
 14:'This asks for two direct signed sums of the supplied joint rates and accelerations, without a frame conversion or a nonparallel-axis transport term.',
 16:'This directly decodes the source shorthand s12 as sin(theta1+theta2). The displayed answer does not require the learner to derive the full elbow acceleration.',
 22:'The acceleration vector is already supplied. Multiply it by the stated mass 2 and apply the stated zero point-mass COM inertia.',
 23:'The item directly identifies the stated zero terminal force as the removed term in f2=R23 f3+F2.',
 32:'This directly recalls that the allowed revolute axis determines the signed moment projection.',
 42:'This asks for the two explicitly summarized recursion passes in their stated order, without computing an iteration.'
}.items():flag(i,'difficulty','Change medium to easy. '+reason)
flag(21,'difficulty','Change hard to medium. The signed rate sum is zero; with zero angular acceleration, the local link2 offset terms vanish, leaving a one-step elbow centripetal-acceleration rotation. The zero-spin/translation distinction is useful but does not demand a hard derivation.')
flag(28,'sourceSupport','Mark the p421 citation as conflicting evidence and add precise question-level conflictResolution metadata bound to the lecture PDF version. The actual expanded term visibly puts a transpose after an already 3×1 n2 column, making literal R12 n2ᵀ nonconformable. The general recurrence at the top of p421 and the column expansion on p422 support R12 n2. The prose currently explains this correctly, but the machine-readable citation still says premise and there is no resolution record. Preserve the source issue; do not label the whole PDF or page globally corrected. The unaffected general recurrence used by Q027 and Q046 does not itself need to be marked false.')
now=datetime.datetime.now(datetime.timezone.utc).isoformat();reviewer=blind['reviewerId'];reviews=[]
for qid,q in qs.items():
 a=answers[qid];checks={k:True for k in CHECK_KEYS}
 for f in flags.get(qid,[]):checks[f['check']]=False
 assert reviewer not in {q['authorId'],*q.get('revisionAuthors',[])}
 refs=q['citations']
 reviews.append({'id':f'REV-{qid}-v1-interface-independent','questionId':qid,'questionVersion':q['version'],'questionSha256':question_hash(q),'reviewerId':reviewer,'decision':'flagged' if qid in flags else 'verified','reviewedAt':now,'sourceVersions':{c['sourceId']:c['sourceSha256'] for c in refs},'reviewedSlideIds':a['reviewedSlideIds'],'sourceInspectionEvidence':[{'physicalPage':c['physicalPage'],'inspectorIds':[reviewer],'previewSha256':hashlib.sha256((R/f"sources/previews/lectures/page-{c['physicalPage']:04d}.webp").read_bytes()).hexdigest()} for c in refs],'independentAnswerOptionIds':a['independentAnswerOptionIds'],'solvedBeforeAnswerSeen':True,'checks':checks,'reasoning':a['reasoning']+' After the saved source-first answer freeze, I checked all keyed options, explanations, steps, formula definitions/units, assumptions and citation locations. All intended keys agree. The dynamics equations were independently compared with Cartesian point-mass virtual work, Jacobian mass matrices, potential gradients, energy rates and finite-difference physical accelerations. The 2,516 executable cases include the question numerical values, gravity signs, rate reversal and terminal-couple propagation. Recall-only items need no separate arithmetic. The actual figure axes, origins, endpoint placements and equations were visually inspected, not inferred solely from OCR. Wrong alternatives represent relevant boundary, frame, lever-arm, rate-sign, inertia or model-scope errors. Deliberate concept/application/special-case contrasts are not excessive duplicates. Any distinct quality/provenance flag is recorded separately.','findings':[f['finding'] for f in flags.get(qid,[])],'reviewType':'independent_blind_initial_review','priorReviewerExposure':False,'priorAuthorExposure':False,'blindAnswersPath':str(blindpath.relative_to(R)),'blindAnswersSha256':hashlib.sha256(blindpath.read_bytes()).hexdigest(),'computationsPath':'audits/W03-L13-independent-computations.json'})
p=R/'data/reviews/W03-L13-v1-independent.json';assert not p.exists();p.write_text(json.dumps(reviews,ensure_ascii=False,indent=2)+'\n')
gaps=[{'physicalPage':408,'kind':'figure/frame conventions','gap':'Add a direct figure-based item distinguishing frame0 and frame1 sharing the base origin but differing in orientation, frame2 at the elbow, and frame3 at the tip aligned with frame2. Existing questions test endpoint masses, elbow/COM coincidence and selected vector rotations but never directly check this complete frame assignment. This is needed to interpret the recursive frame indices correctly.','status':'new draft question required'},{'physicalPage':424,'kind':'method scope/complexity','gap':'Add a concise item on why even the simple 2DOF endpoint-mass closed form is lengthy and why a 6DOF symbolic expansion becomes more complex, motivating the organized recursive evaluation. Do not imply the method is inapplicable, or claim exponential runtime merely from symbolic-expression complexity. Existing Q041 tests inputs and Q042 the pass order, not this explicit source point.','status':'new draft question required'}]
summary={'reviewedAt':now,'reviewed':46,'verified':46-len(flags),'flagged':len(flags),'answerAgreement':46,'answerCorrectionsRequired':0,'independentBlindReview':True,'sourcePagesInspected':list(range(404,428)),'computationGroupsPassed':len(comp['groups']),'computationCasesPassed':comp['caseCount'],'reviewPath':str(p.relative_to(R)),'blindAnswersPath':str(blindpath.relative_to(R)),'reviewedBatchSha256':hashlib.sha256(batchpath.read_bytes()).hexdigest(),'actionableFlags':flags,'flagCountsByCheck':dict(collections.Counter(f['check'] for fs in flags.values() for f in fs)),'approvedCurrentHashes':{r['questionId']:r['questionSha256'] for r in reviews if r['decision']=='verified'},'allReviewedCurrentHashes':{r['questionId']:r['questionSha256'] for r in reviews},'coverageGaps':gaps,'sourceAndScopeNotes':['All 24 actual page images and all extracted text were inspected before opening keyed answers or author sourceIssues. The assigned blind packet hash matches.','Gravity-augmented base acceleration is not physical motion of the fixed base. No terminal wrench does not suppress gravity or internal loads.','Endpoint placement, not point-mass idealization alone, establishes the first-COM/elbow coincidence.','The p421 extraneous transpose is a local source conflict. Its valid general recurrence remains usable for questions that do not rely on the erroneous expanded notation.','No authored question, inspection record, source dispute, canonical bank or Git state was modified.'],'nonblockingStyleNotes':['Minor prose/number joins remain (for example "displayed3×1" and "by2"). Normalize them when versioning the flagged items; do not silently edit accepted hashes.','For standalone formula-sheet clarity, the reusable M(q)qddot+h(q,qdot)+G(q) record could explicitly define q=(theta1,theta2), qdot in rad/s, and the 2×2 matrix M in kg·m². Current joint-angle/rate definitions, entry definitions and source context suffice to interpret the checked questions.','The p423 citation in Q044 is categorized figure although it points to torque equations. Its exact locator and supplied source remain adequate; improve the kind only through a versioned edit if desired.']}
(R/'audits/W03-L13-independent-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
(R/'audits/W03-L13-coverage-gaps.json').write_text(json.dumps(gaps,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:summary[k] for k in ['reviewed','verified','flagged','answerAgreement','computationCasesPassed','flagCountsByCheck']},indent=2))
